(4, 'የሙከራ ማረጋገጫ (Verification)', 'telegram', 'custom_broadcast_selection', 'የቴሌግራም መልእክት ማስተላለፊያ ስርዓቱ አሁን 100% እየሰራ ነው! በዳሽቦርዱ ላይ የፈለጉትን መልእክት ለደንበኞችዎ መላክ ይችላሉ።', 'completed', 1, 1, '0', NULL, NULL, '2026-11-02 23:17:33', '2026-11-02 23:17:33', '2026-11-02 23:17:33'),
(5, 'test', 'telegram', 'custom_broadcast_selection', 'ውድ ደንበኛችን፤ የሜሽ ክሊኒንግ ልዩ የጥልቅ ጽዳት አገልግሎት ቅናሽ ተዘጋጅቶ ይጠብቆታል። አሁኑኑ ቀጠሮዎን ያስይዙ!', 'completed', 1, 1, '0', 1, NULL, '2026-11-02 23:20:32', '2026-11-02 23:20:32', '2026-11-02 23:20:32');
